// The presets the Program button can apply (format: edit.h), kept in the
// preset sector of the flash store:
//   'P' 'S', version (1), active index (0xFF: none), count,
//   count x (length (2, LE), preset)
// A board with an empty or invalid sector uses the built-in defaults
// (default_presets.h, generated by `python -m spdtool.preset --c-defaults`).
#pragma once

#include "err.h"
#include "pico/stdlib.h"

unsigned presets_count(void);
const uint8_t *presets_get(unsigned i, size_t *len);
// Copies the name of preset i into `name`.
void presets_name(unsigned i, char *name, size_t size);
int presets_find(const char *name);  // index or -1
int presets_active(void);            // index or -1
bool presets_builtin(void);          // true while the defaults are in use

err_t presets_use(unsigned i);
// Adds a preset, replacing one with the same name.
err_t presets_add(const uint8_t *p, size_t len);
err_t presets_delete(unsigned i);
// Back to the built-in defaults.
err_t presets_reset(void);
